//! Canonical Document live-name operation and pre-conversion boundaries.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><input id=seed name=match></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://name-method.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){assert_eq!(p.console_eval(d,f,s).errors,0,"{}",p.report());}
#[test]
fn document_name_method_canonical_descriptor_override_delete_restore_and_saved_filter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var proto=Document.prototype,desc=Object.getOwnPropertyDescriptor(proto,'getElementsByName'),saved=proto.getElementsByName,seed=document.getElementById('seed');if(!desc||saved!==document.getElementsByName||saved.name!=='getElementsByName'||saved.length!==1||!desc.writable||!desc.enumerable||!desc.configurable||Object.getOwnPropertyDescriptor(document,'getElementsByName')!==undefined)throw 'canonical descriptor';var list=saved.call(document,'match'),sentinel={};proto.getElementsByName=function(){return sentinel;};if(document.getElementsByName('match')!==sentinel||saved.call(document,'match')[0]!==seed)throw 'ordinary override';if(!delete proto.getElementsByName||document.getElementsByName!==undefined||'getElementsByName' in document||saved.call(document,'match')[0]!==seed)throw 'ordinary deletion';Object.defineProperty(proto,'getElementsByName',desc);seed.setAttribute('name','changed');if(document.getElementsByName!==saved||list.length!==0||saved.call(document,'changed')[0]!==seed||saved.call(document,'A\ud800').length!==0)throw 'restoration and exact live backend';
"#);}
#[test]
fn document_name_method_brand_arity_domstring_and_supported_owners_convert_once(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var method=Document.prototype.getElementsByName,calls=0,query={toString:function(){calls++;return 'match';}};for(var bad of [{},window,Document.prototype,Node.prototype,document.body,document.createDocumentFragment()]){var caught=false;try{method.call(bad,query);}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}for(var args of [[],[Symbol()]]){var caught=false;try{method.apply(document,args);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'required DOMString';}var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);for(var owner of [new Document(),document.implementation.createHTMLDocument('inert'),frame.contentDocument]){var before=calls;if(method.call(owner,query).length!==0||calls!==before+1)throw 'real owner query conversion';}calls=0;if(method.call(document,query,{toString:function(){throw 'extra';}})[0]!==document.getElementById('seed')||calls!==1)throw 'converted once and ignored extra';for(var v of [null,undefined,BigInt(1)])if(method.call(document,v).length!==0)throw 'ordinary DOMString';
"#);}
#[test]
fn document_name_method_child_realm_saved_function_and_origin_preflight(){let(mut d,mut f,mut p)=fixture();p.set_location(&crate::navigation::address("https://name-method.test/",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,r#"
var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Document.prototype.getElementsByName,calls=0,query={toString:function(){calls++;return 'match';}};if(saved.call(document,query)[0]!==document.getElementById('seed')||calls!==1)throw 'saved child canonical method';
"#);p.set_location(&crate::navigation::address("https://other-name-method.test/",&crate::navigation::Location::home()).unwrap());let before=(p.state.retained,p.state.node_lists.len(),p.state.dom_commits);assert_eq!(p.console_eval(&mut d,&mut f,"saved.call(document,query);").errors,1);assert_eq!((p.state.retained,p.state.node_lists.len(),p.state.dom_commits),before);run(&mut d,&mut f,&mut p,"if(calls!==1)throw 'origin before conversion';");}
